-- Sets up a NEW, EMPTY Supabase project for Siza in one go.
-- Generated by scripts/build-setup-sql.mjs from supabase/migrations/. Don't edit by hand.
-- Paste the whole file into the SQL Editor and run it once. It runs as one transaction:
-- if anything fails, nothing is changed.

-- ════════ 0001_schema.sql ════════
-- Extensions
create extension if not exists postgis with schema public;
create extension if not exists pgcrypto with schema public;

-- profiles: one row per auth.users row, created by the app right after signup
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null,
  avatar_url text,
  role text not null check (role in ('client', 'tasker', 'both')),
  bio text,
  rating_avg numeric(3, 2) not null default 0,
  rating_count integer not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.tasks (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.profiles (id) on delete cascade,
  title text not null,
  description text not null,
  category text not null,
  budget numeric(10, 2) not null check (budget > 0),
  status text not null default 'open' check (status in ('open', 'assigned', 'completed', 'cancelled')),
  location geography(point, 4326) not null,
  address_text text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists tasks_location_idx on public.tasks using gist (location);
create index if not exists tasks_status_idx on public.tasks (status);
create index if not exists tasks_client_id_idx on public.tasks (client_id);

create table if not exists public.bids (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks (id) on delete cascade,
  tasker_id uuid not null references public.profiles (id) on delete cascade,
  amount numeric(10, 2) not null check (amount > 0),
  message text,
  status text not null default 'pending' check (status in ('pending', 'accepted', 'rejected')),
  created_at timestamptz not null default now(),
  unique (task_id, tasker_id)
);

create index if not exists bids_task_id_idx on public.bids (task_id);
create index if not exists bids_tasker_id_idx on public.bids (tasker_id);

create table if not exists public.chat_threads (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null unique references public.tasks (id) on delete cascade,
  client_id uuid not null references public.profiles (id) on delete cascade,
  tasker_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);

create table if not exists public.chat_messages (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references public.chat_threads (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  body text not null,
  created_at timestamptz not null default now()
);

create index if not exists chat_messages_thread_id_idx on public.chat_messages (thread_id, created_at);

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null unique references public.tasks (id) on delete cascade,
  stripe_payment_intent_id text not null,
  amount numeric(10, 2) not null,
  status text not null default 'pending' check (status in ('pending', 'succeeded', 'failed')),
  created_at timestamptz not null default now()
);

-- ════════ 0002_rls.sql ════════
alter table public.profiles enable row level security;
alter table public.tasks enable row level security;
alter table public.bids enable row level security;
alter table public.chat_threads enable row level security;
alter table public.chat_messages enable row level security;
alter table public.payments enable row level security;

-- profiles: public read (browsing tasker profiles/ratings), write only your own row
create policy "profiles are readable by any authenticated user"
  on public.profiles for select
  to authenticated
  using (true);

create policy "users can create their own profile"
  on public.profiles for insert
  to authenticated
  with check (id = auth.uid());

create policy "users can update their own profile"
  on public.profiles for update
  to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- tasks: open tasks are publicly browsable; the client and any tasker who bid can also see theirs
create policy "open tasks and own tasks are readable"
  on public.tasks for select
  to authenticated
  using (
    status = 'open'
    or client_id = auth.uid()
    or exists (select 1 from public.bids b where b.task_id = tasks.id and b.tasker_id = auth.uid())
  );

create policy "clients can create tasks"
  on public.tasks for insert
  to authenticated
  with check (client_id = auth.uid());

create policy "clients can update their own tasks"
  on public.tasks for update
  to authenticated
  using (client_id = auth.uid())
  with check (client_id = auth.uid());

create policy "clients can delete their own open tasks"
  on public.tasks for delete
  to authenticated
  using (client_id = auth.uid() and status = 'open');

-- bids: a tasker sees their own bids, a client sees bids on their own tasks
create policy "bids readable by the bidder or the task's client"
  on public.bids for select
  to authenticated
  using (
    tasker_id = auth.uid()
    or exists (select 1 from public.tasks t where t.id = bids.task_id and t.client_id = auth.uid())
  );

create policy "taskers can place bids on open tasks"
  on public.bids for insert
  to authenticated
  with check (
    tasker_id = auth.uid()
    and exists (select 1 from public.tasks t where t.id = bids.task_id and t.status = 'open')
  );

create policy "taskers can update their own pending bids"
  on public.bids for update
  to authenticated
  using (tasker_id = auth.uid() and status = 'pending')
  with check (tasker_id = auth.uid());

create policy "clients can accept or reject bids on their tasks"
  on public.bids for update
  to authenticated
  using (exists (select 1 from public.tasks t where t.id = bids.task_id and t.client_id = auth.uid()))
  with check (exists (select 1 from public.tasks t where t.id = bids.task_id and t.client_id = auth.uid()));

-- chat: only the two participants on a task can see/create their thread and messages
create policy "participants can read their chat threads"
  on public.chat_threads for select
  to authenticated
  using (client_id = auth.uid() or tasker_id = auth.uid());

create policy "participants can create their chat thread"
  on public.chat_threads for insert
  to authenticated
  with check (client_id = auth.uid() or tasker_id = auth.uid());

create policy "participants can read messages in their threads"
  on public.chat_messages for select
  to authenticated
  using (
    exists (
      select 1 from public.chat_threads th
      where th.id = chat_messages.thread_id
        and (th.client_id = auth.uid() or th.tasker_id = auth.uid())
    )
  );

create policy "participants can send messages in their threads"
  on public.chat_messages for insert
  to authenticated
  with check (
    sender_id = auth.uid()
    and exists (
      select 1 from public.chat_threads th
      where th.id = chat_messages.thread_id
        and (th.client_id = auth.uid() or th.tasker_id = auth.uid())
    )
  );

-- payments: readable by the task's client or the accepted tasker; writes only via the
-- service-role key from the create-payment-intent Edge Function, so no insert/update policy here
create policy "task participants can read payment status"
  on public.payments for select
  to authenticated
  using (
    exists (
      select 1 from public.tasks t
      where t.id = payments.task_id
        and (
          t.client_id = auth.uid()
          or exists (
            select 1 from public.bids b
            where b.task_id = t.id and b.tasker_id = auth.uid() and b.status = 'accepted'
          )
        )
    )
  );

-- ════════ 0003_functions.sql ════════
-- keep tasks.updated_at current
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists tasks_set_updated_at on public.tasks;
create trigger tasks_set_updated_at
  before update on public.tasks
  for each row
  execute function public.set_updated_at();

-- nearby open tasks, ordered by distance. RLS on tasks still applies since this is
-- a plain (non security definer) function running as the calling user.
create or replace function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  address_text text,
  created_at timestamptz,
  distance_meters double precision
)
language sql
stable
as $$
  select
    t.id, t.client_id, t.title, t.description, t.category, t.budget, t.status,
    t.address_text, t.created_at,
    st_distance(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography) as distance_meters
  from public.tasks t
  where t.status = 'open'
    and st_dwithin(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography, radius_meters)
    and (category_filter is null or t.category = category_filter)
  order by distance_meters asc;
$$;

-- Atomically accept one bid: reject the other pending bids, mark the task assigned,
-- and open a chat thread between the client and the winning tasker.
-- security definer so the multi-table write succeeds under a single authorization check,
-- rather than relying on the client to run three separate RLS-gated statements.
create or replace function public.accept_bid(bid_id uuid)
returns public.chat_threads
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_bid public.bids;
  v_thread public.chat_threads;
begin
  select * into v_bid from public.bids where id = bid_id;
  if v_bid is null then
    raise exception 'bid not found';
  end if;

  select * into v_task from public.tasks where id = v_bid.task_id;
  if v_task is null then
    raise exception 'task not found';
  end if;

  if v_task.client_id <> auth.uid() then
    raise exception 'only the task client can accept a bid';
  end if;

  if v_task.status <> 'open' then
    raise exception 'task is not open for bidding';
  end if;

  update public.bids set status = 'accepted' where id = v_bid.id;
  update public.bids set status = 'rejected' where task_id = v_task.id and id <> v_bid.id and status = 'pending';
  update public.tasks set status = 'assigned' where id = v_task.id;

  insert into public.chat_threads (task_id, client_id, tasker_id)
  values (v_task.id, v_task.client_id, v_bid.tasker_id)
  on conflict (task_id) do update set task_id = excluded.task_id
  returning * into v_thread;

  return v_thread;
end;
$$;

-- ════════ 0004_realtime.sql ════════
-- Stream new chat messages to subscribed clients in real time.
alter publication supabase_realtime add table public.chat_messages;

-- ════════ 0005_profile_creation_trigger.sql ════════
-- Create the profiles row server-side, right when the auth user is created, instead of
-- from the client. This decouples it from email-confirmation timing: signUp() only
-- returns a session once the email is confirmed, so a client-side insert right after
-- signUp runs unauthenticated and gets rejected by RLS ("profiles are insertable by
-- their own user, to authenticated"). full_name/role are passed in via
-- supabase.auth.signUp({ options: { data: { full_name, role } } }) and land in
-- auth.users.raw_user_meta_data, which this trigger reads.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    coalesce(new.raw_user_meta_data->>'role', 'client')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row
  execute function public.handle_new_user();

-- Backfill any auth.users created before this trigger existed (e.g. signups that hit
-- the RLS error above and never got a profiles row).
insert into public.profiles (id, full_name, role)
select
  u.id,
  coalesce(u.raw_user_meta_data->>'full_name', ''),
  coalesce(u.raw_user_meta_data->>'role', 'client')
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id);

-- ════════ 0006_fix_rls_recursion.sql ════════
-- tasks' select policy reads bids (to let a tasker see a task they bid on), and bids'
-- policies read tasks (to let a client see/manage bids on their task) — evaluating either
-- policy triggers the other table's RLS, which triggers the first again, which Postgres
-- reports as "infinite recursion detected in policy for relation tasks". These
-- SECURITY DEFINER helpers run as the function owner, which (as the tables' owner)
-- bypasses RLS entirely, so the cross-table checks no longer re-enter each other's policies.

create or replace function public.is_task_open(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.tasks where id = p_task_id and status = 'open');
$$;

create or replace function public.is_task_client(p_task_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.tasks where id = p_task_id and client_id = p_user_id);
$$;

create or replace function public.has_bid_on_task(p_task_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.bids where task_id = p_task_id and tasker_id = p_user_id);
$$;

grant execute on function public.is_task_open(uuid) to authenticated;
grant execute on function public.is_task_client(uuid, uuid) to authenticated;
grant execute on function public.has_bid_on_task(uuid, uuid) to authenticated;

drop policy if exists "open tasks and own tasks are readable" on public.tasks;
create policy "open tasks and own tasks are readable"
  on public.tasks for select
  to authenticated
  using (
    status = 'open'
    or client_id = auth.uid()
    or public.has_bid_on_task(id, auth.uid())
  );

drop policy if exists "bids readable by the bidder or the task's client" on public.bids;
create policy "bids readable by the bidder or the task's client"
  on public.bids for select
  to authenticated
  using (
    tasker_id = auth.uid()
    or public.is_task_client(task_id, auth.uid())
  );

drop policy if exists "taskers can place bids on open tasks" on public.bids;
create policy "taskers can place bids on open tasks"
  on public.bids for insert
  to authenticated
  with check (
    tasker_id = auth.uid()
    and public.is_task_open(task_id)
  );

drop policy if exists "clients can accept or reject bids on their tasks" on public.bids;
create policy "clients can accept or reject bids on their tasks"
  on public.bids for update
  to authenticated
  using (public.is_task_client(task_id, auth.uid()))
  with check (public.is_task_client(task_id, auth.uid()));

-- ════════ 0007_realtime_tasks_bids.sql ════════
-- Stream task/bid status changes to subscribed clients, so a tasker's screen updates
-- live the moment a client accepts their bid, instead of only refreshing on next fetch.
alter publication supabase_realtime add table public.tasks;
alter publication supabase_realtime add table public.bids;

-- ════════ 0008_ratings.sql ════════
create table if not exists public.ratings (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks (id) on delete cascade,
  rater_id uuid not null references public.profiles (id) on delete cascade,
  ratee_id uuid not null references public.profiles (id) on delete cascade,
  stars smallint not null check (stars between 1 and 5),
  comment text,
  created_at timestamptz not null default now(),
  unique (task_id, rater_id)
);

create index if not exists ratings_ratee_id_idx on public.ratings (ratee_id);

alter table public.ratings enable row level security;

create policy "ratings are publicly readable"
  on public.ratings for select
  to authenticated
  using (true);

-- No direct insert/update policy: all writes go through submit_rating() below, which
-- validates that the caller actually participated in a completed task before recomputing
-- the ratee's aggregate, atomically and without exposing a race to arbitrary client inserts.
create or replace function public.submit_rating(
  p_task_id uuid,
  p_ratee_id uuid,
  p_stars smallint,
  p_comment text default null
)
returns public.ratings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_rater_id uuid := auth.uid();
  v_accepted_tasker_id uuid;
  v_rating public.ratings;
begin
  if p_stars < 1 or p_stars > 5 then
    raise exception 'stars must be between 1 and 5';
  end if;

  select * into v_task from public.tasks where id = p_task_id;
  if v_task is null then
    raise exception 'task not found';
  end if;
  if v_task.status <> 'completed' then
    raise exception 'task must be completed before rating';
  end if;

  select tasker_id into v_accepted_tasker_id from public.bids where task_id = p_task_id and status = 'accepted';

  if v_rater_id = v_task.client_id and p_ratee_id = v_accepted_tasker_id then
    -- client rating the tasker: ok
  elsif v_rater_id = v_accepted_tasker_id and p_ratee_id = v_task.client_id then
    -- tasker rating the client: ok
  else
    raise exception 'you are not a participant on this task, or the ratee is invalid';
  end if;

  insert into public.ratings (task_id, rater_id, ratee_id, stars, comment)
  values (p_task_id, v_rater_id, p_ratee_id, p_stars, p_comment)
  on conflict (task_id, rater_id) do update set stars = excluded.stars, comment = excluded.comment
  returning * into v_rating;

  update public.profiles
  set
    rating_count = (select count(*) from public.ratings where ratee_id = p_ratee_id),
    rating_avg = (select round(avg(stars)::numeric, 2) from public.ratings where ratee_id = p_ratee_id)
  where id = p_ratee_id;

  return v_rating;
end;
$$;

grant execute on function public.submit_rating(uuid, uuid, smallint, text) to authenticated;

-- ════════ 0009_ratings_realtime.sql ════════
alter publication supabase_realtime add table public.ratings;

-- ════════ 0010_storage_and_task_images.sql ════════
alter table public.tasks add column if not exists image_url text;

insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do nothing;

insert into storage.buckets (id, name, public)
values ('task-images', 'task-images', true)
on conflict (id) do nothing;

-- avatars/{user_id}/... : anyone can view (bucket is public), only the owning user can write
create policy "avatar images are publicly accessible"
  on storage.objects for select
  using (bucket_id = 'avatars');

create policy "users can upload their own avatar"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "users can update their own avatar"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "users can delete their own avatar"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

-- task-images/{task_id}/... : anyone can view, only the task's client can write
create policy "task images are publicly accessible"
  on storage.objects for select
  using (bucket_id = 'task-images');

create policy "task clients can upload their task images"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'task-images'
    and exists (
      select 1 from public.tasks t
      where t.id::text = (storage.foldername(name))[1] and t.client_id = auth.uid()
    )
  );

create policy "task clients can update their task images"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'task-images'
    and exists (
      select 1 from public.tasks t
      where t.id::text = (storage.foldername(name))[1] and t.client_id = auth.uid()
    )
  );

create policy "task clients can delete their task images"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'task-images'
    and exists (
      select 1 from public.tasks t
      where t.id::text = (storage.foldername(name))[1] and t.client_id = auth.uid()
    )
  );

-- ════════ 0011_nearby_tasks_image.sql ════════
-- CREATE OR REPLACE can't change a function's return column list, so drop first.
drop function if exists public.nearby_open_tasks(double precision, double precision, integer, text);

create function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  address_text text,
  image_url text,
  created_at timestamptz,
  distance_meters double precision
)
language sql
stable
as $$
  select
    t.id, t.client_id, t.title, t.description, t.category, t.budget, t.status,
    t.address_text, t.image_url, t.created_at,
    st_distance(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography) as distance_meters
  from public.tasks t
  where t.status = 'open'
    and st_dwithin(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography, radius_meters)
    and (category_filter is null or t.category = category_filter)
  order by distance_meters asc;
$$;

-- ════════ 0012_nearby_tasks_coords.sql ════════
-- Return lat/lng so the Browse screen can pin tasks on a map. The return column list
-- changes, so drop first (CREATE OR REPLACE can't alter a function's return type).
drop function if exists public.nearby_open_tasks(double precision, double precision, integer, text);

create function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  address_text text,
  image_url text,
  created_at timestamptz,
  distance_meters double precision,
  task_lat double precision,
  task_lng double precision
)
language sql
stable
as $$
  select
    t.id, t.client_id, t.title, t.description, t.category, t.budget, t.status,
    t.address_text, t.image_url, t.created_at,
    st_distance(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography) as distance_meters,
    st_y(t.location::geometry) as task_lat,
    st_x(t.location::geometry) as task_lng
  from public.tasks t
  where t.status = 'open'
    and st_dwithin(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography, radius_meters)
    and (category_filter is null or t.category = category_filter)
  order by distance_meters asc;
$$;

-- ════════ 0013_realtime_chat_threads.sql ════════
-- Let the Messages inbox pick up a newly opened conversation (created by accept_bid)
-- without a manual refresh.
alter publication supabase_realtime add table public.chat_threads;

-- ════════ 0014_task_scheduled_for.sql ════════
-- When the client needs the task done. Null means flexible timing.
alter table public.tasks add column if not exists scheduled_for timestamptz;

-- Return it from the Browse RPC too. Recreated in full (including the map coordinates from
-- 0012), so this migration works whether or not 0012 has been applied yet.
drop function if exists public.nearby_open_tasks(double precision, double precision, integer, text);

create function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  address_text text,
  image_url text,
  scheduled_for timestamptz,
  created_at timestamptz,
  distance_meters double precision,
  task_lat double precision,
  task_lng double precision
)
language sql
stable
as $$
  select
    t.id, t.client_id, t.title, t.description, t.category, t.budget, t.status,
    t.address_text, t.image_url, t.scheduled_for, t.created_at,
    st_distance(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography) as distance_meters,
    st_y(t.location::geometry) as task_lat,
    st_x(t.location::geometry) as task_lng
  from public.tasks t
  where t.status = 'open'
    and st_dwithin(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography, radius_meters)
    and (category_filter is null or t.category = category_filter)
  order by distance_meters asc;
$$;

-- ════════ 0015_paystack_reference.sql ════════
-- Payments moved from Stripe to Paystack. The Stripe-specific PaymentIntent id column
-- becomes a provider-neutral transaction reference (Paystack's `reference`).
alter table public.payments rename column stripe_payment_intent_id to reference;

-- ════════ 0016_activity_feed_and_unread.sql ════════
-- Activity feed + unread chat tracking.
--
-- Feed entries are written by triggers (security definer), never by the app, so a user is
-- notified no matter whose device caused the event, and nobody can forge or skip an entry.

-- ── Helpers ──────────────────────────────────────────────────────────────────────────────

-- "R 1 250" — mirrors the app's formatMoney().
create or replace function public.format_rand(amount numeric)
returns text
language sql
immutable
as $$
  select 'R ' || replace(to_char(round(amount), 'FM999,999,999,990'), ',', ' ');
$$;

-- ── Activity feed ────────────────────────────────────────────────────────────────────────

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('new_bid', 'bid_accepted', 'bid_rejected', 'task_paid', 'new_review')),
  title text not null,
  body text,
  task_id uuid references public.tasks (id) on delete cascade,
  actor_id uuid references public.profiles (id) on delete set null,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists notifications_user_created_idx on public.notifications (user_id, created_at desc);

alter table public.notifications enable row level security;

drop policy if exists "users read their own notifications" on public.notifications;
create policy "users read their own notifications"
  on public.notifications for select
  to authenticated
  using (user_id = auth.uid());

-- No insert/update policies: rows come from the triggers below, and "read" is set by
-- mark_notifications_read() with the server's clock.
create or replace function public.mark_notifications_read()
returns void
language sql
security definer
set search_path = public
as $$
  update public.notifications set read_at = now() where user_id = auth.uid() and read_at is null;
$$;

grant execute on function public.mark_notifications_read() to authenticated;

-- A tasker bid on your task → tell the client.
create or replace function public.notify_new_bid()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_tasker_name text;
begin
  select * into v_task from public.tasks where id = new.task_id;
  select full_name into v_tasker_name from public.profiles where id = new.tasker_id;

  insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
  values (
    v_task.client_id,
    'new_bid',
    coalesce(nullif(v_tasker_name, ''), 'A tasker') || ' bid ' || public.format_rand(new.amount),
    'on ' || v_task.title,
    new.task_id,
    new.tasker_id
  );
  return new;
end;
$$;

drop trigger if exists bids_notify_new on public.bids;
create trigger bids_notify_new
  after insert on public.bids
  for each row
  execute function public.notify_new_bid();

-- Your bid was accepted or passed over → tell the tasker.
create or replace function public.notify_bid_status()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_client_name text;
begin
  if new.status = old.status or new.status not in ('accepted', 'rejected') then
    return new;
  end if;

  select * into v_task from public.tasks where id = new.task_id;
  select full_name into v_client_name from public.profiles where id = v_task.client_id;

  if new.status = 'accepted' then
    insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
    values (
      new.tasker_id,
      'bid_accepted',
      'Your bid was accepted!',
      coalesce(nullif(v_client_name, ''), 'The client') || ' hired you for ' || v_task.title,
      new.task_id,
      v_task.client_id
    );
  else
    insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
    values (
      new.tasker_id,
      'bid_rejected',
      'Bid not selected',
      v_task.title || ' went to another tasker this time',
      new.task_id,
      v_task.client_id
    );
  end if;
  return new;
end;
$$;

drop trigger if exists bids_notify_status on public.bids;
create trigger bids_notify_status
  after update of status on public.bids
  for each row
  execute function public.notify_bid_status();

-- The task was paid and completed → tell the tasker who did it.
create or replace function public.notify_task_paid()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tasker_id uuid;
  v_amount numeric;
begin
  if new.status <> 'completed' or old.status = 'completed' then
    return new;
  end if;

  select tasker_id, amount into v_tasker_id, v_amount
  from public.bids
  where task_id = new.id and status = 'accepted';
  if v_tasker_id is null then
    return new;
  end if;

  insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
  values (
    v_tasker_id,
    'task_paid',
    'Payment received',
    public.format_rand(v_amount) || ' for ' || new.title,
    new.id,
    new.client_id
  );
  return new;
end;
$$;

drop trigger if exists tasks_notify_paid on public.tasks;
create trigger tasks_notify_paid
  after update of status on public.tasks
  for each row
  execute function public.notify_task_paid();

-- Someone reviewed you → tell the person reviewed.
create or replace function public.notify_new_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rater_name text;
begin
  select full_name into v_rater_name from public.profiles where id = new.rater_id;

  insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
  values (
    new.ratee_id,
    'new_review',
    coalesce(nullif(v_rater_name, ''), 'Someone') || ' left you a review',
    repeat('⭐', new.stars) || coalesce(' "' || left(new.comment, 80) || '"', ''),
    new.task_id,
    new.rater_id
  );
  return new;
end;
$$;

drop trigger if exists ratings_notify_new on public.ratings;
create trigger ratings_notify_new
  after insert on public.ratings
  for each row
  execute function public.notify_new_review();

-- ── Unread chat messages ─────────────────────────────────────────────────────────────────

-- When each participant last read each thread. Messages from the other person after that
-- moment are unread.
create table if not exists public.chat_reads (
  thread_id uuid not null references public.chat_threads (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  last_read_at timestamptz not null default now(),
  primary key (thread_id, user_id)
);

alter table public.chat_reads enable row level security;

drop policy if exists "users read their own read markers" on public.chat_reads;
create policy "users read their own read markers"
  on public.chat_reads for select
  to authenticated
  using (user_id = auth.uid());

-- Stamped with the server's clock so a phone with a wrong clock can't hide or resurrect messages.
create or replace function public.mark_thread_read(p_thread_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.chat_threads
    where id = p_thread_id and (client_id = auth.uid() or tasker_id = auth.uid())
  ) then
    raise exception 'not a participant in this conversation';
  end if;

  insert into public.chat_reads (thread_id, user_id, last_read_at)
  values (p_thread_id, auth.uid(), now())
  on conflict (thread_id, user_id) do update set last_read_at = excluded.last_read_at;
end;
$$;

grant execute on function public.mark_thread_read(uuid) to authenticated;

-- Unread message count per thread for the caller (only threads with something unread).
create or replace function public.my_unread_counts()
returns table (thread_id uuid, unread bigint)
language sql
stable
security definer
set search_path = public
as $$
  select th.id, count(m.id)
  from public.chat_threads th
  left join public.chat_reads r on r.thread_id = th.id and r.user_id = auth.uid()
  join public.chat_messages m
    on m.thread_id = th.id
   and m.sender_id <> auth.uid()
   and m.created_at > coalesce(r.last_read_at, '-infinity'::timestamptz)
  where th.client_id = auth.uid() or th.tasker_id = auth.uid()
  group by th.id;
$$;

grant execute on function public.my_unread_counts() to authenticated;

-- Existing conversations start out "read", so old history doesn't light up as unread.
insert into public.chat_reads (thread_id, user_id, last_read_at)
select id, client_id, now() from public.chat_threads
union all
select id, tasker_id, now() from public.chat_threads
on conflict do nothing;

-- ── Realtime ─────────────────────────────────────────────────────────────────────────────

-- Live bell updates. Wrapped so re-running this migration doesn't fail on "already a member".
do $$
begin
  alter publication supabase_realtime add table public.notifications;
exception when duplicate_object then null;
end;
$$;

-- ════════ 0017_security_hardening.sql ════════
-- Security hardening, prompted by the Supabase Security Advisor.
--
-- Postgres grants EXECUTE on every new function to PUBLIC, so anyone holding the anon key
-- could call our SECURITY DEFINER functions directly over the API. Most of them check
-- auth.uid() themselves, but the RLS helper functions answer questions like "has user X bid
-- on task Y?" for any X. This migration closes that, pins search paths, and locks down the
-- PostGIS reference table.

-- ── 1. RLS helper functions move to a schema the API doesn't expose ──────────────────────
-- Policies can still call them (authenticated gets USAGE + EXECUTE), but they're no longer
-- reachable as /rest/v1/rpc/... endpoints.

create schema if not exists private;
grant usage on schema private to authenticated;

create or replace function private.is_task_open(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.tasks where id = p_task_id and status = 'open');
$$;

create or replace function private.is_task_client(p_task_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.tasks where id = p_task_id and client_id = p_user_id);
$$;

create or replace function private.has_bid_on_task(p_task_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.bids where task_id = p_task_id and tasker_id = p_user_id);
$$;

revoke all on function private.is_task_open(uuid) from public;
revoke all on function private.is_task_client(uuid, uuid) from public;
revoke all on function private.has_bid_on_task(uuid, uuid) from public;
grant execute on function private.is_task_open(uuid) to authenticated;
grant execute on function private.is_task_client(uuid, uuid) to authenticated;
grant execute on function private.has_bid_on_task(uuid, uuid) to authenticated;

-- Same policies as 0006, pointed at the private helpers.
drop policy if exists "open tasks and own tasks are readable" on public.tasks;
create policy "open tasks and own tasks are readable"
  on public.tasks for select
  to authenticated
  using (
    status = 'open'
    or client_id = auth.uid()
    or private.has_bid_on_task(id, auth.uid())
  );

drop policy if exists "bids readable by the bidder or the task's client" on public.bids;
create policy "bids readable by the bidder or the task's client"
  on public.bids for select
  to authenticated
  using (
    tasker_id = auth.uid()
    or private.is_task_client(task_id, auth.uid())
  );

drop policy if exists "taskers can place bids on open tasks" on public.bids;
create policy "taskers can place bids on open tasks"
  on public.bids for insert
  to authenticated
  with check (
    tasker_id = auth.uid()
    and private.is_task_open(task_id)
  );

drop policy if exists "clients can accept or reject bids on their tasks" on public.bids;
create policy "clients can accept or reject bids on their tasks"
  on public.bids for update
  to authenticated
  using (private.is_task_client(task_id, auth.uid()))
  with check (private.is_task_client(task_id, auth.uid()));

drop function if exists public.is_task_open(uuid);
drop function if exists public.is_task_client(uuid, uuid);
drop function if exists public.has_bid_on_task(uuid, uuid);

-- ── 2. Trigger functions: nobody needs to call these directly ────────────────────────────
-- Triggers still fire normally; EXECUTE is only checked when a function is called directly.

revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.set_updated_at() from public, anon, authenticated;
revoke all on function public.notify_new_bid() from public, anon, authenticated;
revoke all on function public.notify_bid_status() from public, anon, authenticated;
revoke all on function public.notify_task_paid() from public, anon, authenticated;
revoke all on function public.notify_new_review() from public, anon, authenticated;

-- ── 3. App RPCs: signed-in users only ────────────────────────────────────────────────────
-- These stay callable by `authenticated` on purpose (the app uses them, and each checks
-- auth.uid() itself), so the advisor may keep listing them as an informational warning.

revoke all on function public.accept_bid(uuid) from public, anon;
revoke all on function public.submit_rating(uuid, uuid, smallint, text) from public, anon;
revoke all on function public.mark_notifications_read() from public, anon;
revoke all on function public.mark_thread_read(uuid) from public, anon;
revoke all on function public.my_unread_counts() from public, anon;
grant execute on function public.accept_bid(uuid) to authenticated;
grant execute on function public.submit_rating(uuid, uuid, smallint, text) to authenticated;
grant execute on function public.mark_notifications_read() to authenticated;
grant execute on function public.mark_thread_read(uuid) to authenticated;
grant execute on function public.my_unread_counts() to authenticated;

-- ── 4. Pin search_path on the functions that didn't set one ──────────────────────────────

alter function public.set_updated_at() set search_path = public;
alter function public.nearby_open_tasks(double precision, double precision, integer, text) set search_path = public;
alter function public.format_rand(numeric) set search_path = public;

-- ── 5. PostGIS's spatial_ref_sys table ───────────────────────────────────────────────────
-- It's PostGIS's catalogue of coordinate systems (no user data), created in `public`
-- because PostGIS was installed there. Distance queries on geography columns read it, so it
-- must stay readable. Writes are what to prevent. On Supabase this table may be owned by an
-- internal role, in which case these statements aren't permitted; each is attempted
-- separately so the rest of this migration still applies.

do $$
begin
  alter table public.spatial_ref_sys enable row level security;
  drop policy if exists "coordinate systems are readable" on public.spatial_ref_sys;
  create policy "coordinate systems are readable"
    on public.spatial_ref_sys for select
    to anon, authenticated
    using (true);
exception when insufficient_privilege then
  raise notice 'spatial_ref_sys: not the owner, could not enable RLS (see README)';
end;
$$;

do $$
begin
  revoke insert, update, delete, truncate on public.spatial_ref_sys from anon, authenticated;
exception when insufficient_privilege then
  raise notice 'spatial_ref_sys: could not revoke write privileges';
end;
$$;

-- ════════ 0018_move_postgis_to_extensions.sql ════════
-- Move PostGIS out of `public` into Supabase's `extensions` schema.
--
-- With PostGIS in `public`, its spatial_ref_sys table is exposed through the API with no RLS,
-- and Supabase doesn't let us enable RLS on it (an internal role owns it), so anyone with the
-- anon key could edit PostGIS's coordinate-system definitions. The `extensions` schema isn't
-- exposed. This clears the Security Advisor's "RLS Disabled in Public" (spatial_ref_sys) and
-- "Extension in Public" (postgis) findings.
--
-- An extension can't be moved in place, so this reinstalls it. Dropping PostGIS also drops
-- tasks.location, so each task's coordinates are saved first and restored afterwards.
--
-- Run it as one script: the SQL Editor runs a multi-statement script as a single
-- transaction, so if any step fails nothing changes, task locations included.

-- 1. Save every task's coordinates.
create temp table task_location_backup on commit drop as
select id, st_x(location::geometry) as lng, st_y(location::geometry) as lat
from public.tasks;

-- 2. Reinstall PostGIS in the extensions schema. CASCADE drops tasks.location and its index.
drop extension if exists postgis cascade;
create schema if not exists extensions;
create extension postgis with schema extensions;

-- 3. Recreate the location column and restore the saved coordinates.
alter table public.tasks add column location extensions.geography(point, 4326);

update public.tasks t
set location = extensions.st_setsrid(extensions.st_makepoint(b.lng, b.lat), 4326)::extensions.geography
from task_location_backup b
where b.id = t.id;

alter table public.tasks alter column location set not null;
create index if not exists tasks_location_idx on public.tasks using gist (location);

-- 4. Recreate the Browse search so it finds PostGIS in its new schema.
drop function if exists public.nearby_open_tasks(double precision, double precision, integer, text);

create function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  address_text text,
  image_url text,
  scheduled_for timestamptz,
  created_at timestamptz,
  distance_meters double precision,
  task_lat double precision,
  task_lng double precision
)
language sql
stable
set search_path = public, extensions
as $$
  select
    t.id, t.client_id, t.title, t.description, t.category, t.budget, t.status,
    t.address_text, t.image_url, t.scheduled_for, t.created_at,
    st_distance(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography) as distance_meters,
    st_y(t.location::geometry) as task_lat,
    st_x(t.location::geometry) as task_lng
  from public.tasks t
  where t.status = 'open'
    and st_dwithin(t.location, st_setsrid(st_makepoint(lng, lat), 4326)::geography, radius_meters)
    and (category_filter is null or t.category = category_filter)
  order by distance_meters asc;
$$;

-- 5. Safety check: abort (rolling everything back) if any task lost its location.
do $$
declare
  v_missing integer;
begin
  select count(*) into v_missing from public.tasks where location is null;
  if v_missing > 0 then
    raise exception '% task(s) lost their location; rolling back', v_missing;
  end if;
end;
$$;

-- ════════ 0019_integrity_guards.sql ════════
-- Integrity guards: what a signed-in user may change by calling the API directly.
--
-- Row Level Security decides WHICH ROWS a user can write. It doesn't decide which columns
-- or which values, so until now, with nothing but the app's public key and their own login:
--   * a client could mark their task 'completed' without paying;
--   * a tasker could set their own bid to 'accepted';
--   * a client could lower a tasker's bid amount, then accept it;
--   * anyone could set their own rating_avg / rating_count;
--   * anyone could open a chat thread with any other user.
--
-- The guards below are BEFORE triggers that apply only to direct API requests, where
-- current_user is 'authenticated' (or 'anon'). The app's SECURITY DEFINER functions
-- (accept_bid, submit_rating, ...) run as their owner and Edge Functions as service_role, so
-- they pass through untouched and remain the only way to make the protected changes.
--
-- The guard functions must stay SECURITY INVOKER: that's what makes current_user the caller.

-- ── Profiles: ratings are computed, never typed in ───────────────────────────────────────

create or replace function public.guard_profile_write()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.rating_avg := 0;
    new.rating_count := 0;
  else
    new.id := old.id;
    new.rating_avg := old.rating_avg;
    new.rating_count := old.rating_count;
    new.created_at := old.created_at;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_write on public.profiles;
create trigger profiles_guard_write
  before insert or update on public.profiles
  for each row
  execute function public.guard_profile_write();

-- ── Tasks: assigned by accept_bid(), completed by a verified payment ─────────────────────

create or replace function public.guard_task_write()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'open';
    return new;
  end if;

  if old.status <> 'open' then
    raise exception 'This task can no longer be changed.' using errcode = '42501';
  end if;
  if new.status not in ('open', 'cancelled') then
    raise exception 'A task is assigned by accepting a bid and completed by paying for it.' using errcode = '42501';
  end if;

  new.id := old.id;
  new.client_id := old.client_id;
  new.created_at := old.created_at;
  return new;
end;
$$;

drop trigger if exists tasks_guard_write on public.tasks;
create trigger tasks_guard_write
  before insert or update on public.tasks
  for each row
  execute function public.guard_task_write();

-- ── Bids: the bidder owns the offer, the client only gets to answer it ───────────────────

-- A tasker can now take a pending bid back ('withdrawn') and bid again later.
alter table public.bids drop constraint if exists bids_status_check;
alter table public.bids
  add constraint bids_status_check check (status in ('pending', 'accepted', 'rejected', 'withdrawn'));

create or replace function public.guard_bid_write()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'pending';
    if private.is_task_client(new.task_id, auth.uid()) then
      raise exception 'You can''t bid on your own task.' using errcode = '42501';
    end if;
    return new;
  end if;

  new.id := old.id;
  new.task_id := old.task_id;
  new.tasker_id := old.tasker_id;
  new.created_at := old.created_at;

  if old.tasker_id = auth.uid() then
    -- The bidder: revise or withdraw a pending bid, or put a withdrawn one back while the
    -- task is still open. Never accept or reject it.
    if old.status = 'pending' and new.status in ('pending', 'withdrawn') then
      return new;
    end if;
    if old.status = 'withdrawn' and new.status = 'pending' and private.is_task_open(old.task_id) then
      return new;
    end if;
    raise exception 'This bid can no longer be changed.' using errcode = '42501';
  end if;

  -- The task's client: may decline a pending bid, nothing else. Accepting goes through
  -- accept_bid(), which also assigns the task and opens the chat.
  if new.amount is distinct from old.amount or new.message is distinct from old.message then
    raise exception 'Only the tasker can change their bid.' using errcode = '42501';
  end if;
  if new.status is distinct from old.status and not (old.status = 'pending' and new.status = 'rejected') then
    raise exception 'Use Accept bid to hire a tasker.' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists bids_guard_write on public.bids;
create trigger bids_guard_write
  before insert or update on public.bids
  for each row
  execute function public.guard_bid_write();

-- The old policy only let a tasker touch a bid while it was pending; re-bidding after a
-- withdrawal needs the withdrawn row too. What they may change is the guard's job.
drop policy if exists "taskers can update their own pending bids" on public.bids;
drop policy if exists "taskers can update their own open bids" on public.bids;
create policy "taskers can update their own open bids"
  on public.bids for update
  to authenticated
  using (tasker_id = auth.uid() and status in ('pending', 'withdrawn'))
  with check (tasker_id = auth.uid());

-- accept_bid() used to accept a bid in any state (e.g. one already rejected). Same function,
-- plus a check that the bid is still on the table.
create or replace function public.accept_bid(bid_id uuid)
returns public.chat_threads
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_bid public.bids;
  v_thread public.chat_threads;
begin
  select * into v_bid from public.bids where id = bid_id;
  if v_bid is null then
    raise exception 'bid not found';
  end if;

  select * into v_task from public.tasks where id = v_bid.task_id for update;
  if v_task is null then
    raise exception 'task not found';
  end if;

  if v_task.client_id <> auth.uid() then
    raise exception 'only the task client can accept a bid';
  end if;

  if v_task.status <> 'open' then
    raise exception 'task is not open for bidding';
  end if;

  if v_bid.status <> 'pending' then
    raise exception 'This bid is no longer available.';
  end if;

  update public.bids set status = 'accepted' where id = v_bid.id;
  update public.bids set status = 'rejected' where task_id = v_task.id and id <> v_bid.id and status = 'pending';
  update public.tasks set status = 'assigned' where id = v_task.id;

  insert into public.chat_threads (task_id, client_id, tasker_id)
  values (v_task.id, v_task.client_id, v_bid.tasker_id)
  on conflict (task_id) do update set task_id = excluded.task_id
  returning * into v_thread;

  return v_thread;
end;
$$;

revoke all on function public.accept_bid(uuid) from public, anon;
grant execute on function public.accept_bid(uuid) to authenticated;

-- ── Chat threads: only accept_bid() opens one ────────────────────────────────────────────

drop policy if exists "participants can create their chat thread" on public.chat_threads;

-- ── Trigger functions aren't callable as API endpoints ───────────────────────────────────

revoke all on function public.guard_profile_write() from public, anon, authenticated;
revoke all on function public.guard_task_write() from public, anon, authenticated;
revoke all on function public.guard_bid_write() from public, anon, authenticated;

-- ── Size limits on user-entered text and money ───────────────────────────────────────────
-- NOT VALID: enforced for every new or changed row, without failing on rows that already
-- exist.

alter table public.profiles drop constraint if exists profiles_full_name_length;
alter table public.profiles add constraint profiles_full_name_length check (char_length(full_name) <= 80) not valid;
alter table public.profiles drop constraint if exists profiles_bio_length;
alter table public.profiles add constraint profiles_bio_length check (bio is null or char_length(bio) <= 1000) not valid;

alter table public.tasks drop constraint if exists tasks_title_length;
alter table public.tasks add constraint tasks_title_length check (char_length(btrim(title)) between 3 and 120) not valid;
alter table public.tasks drop constraint if exists tasks_description_length;
alter table public.tasks add constraint tasks_description_length check (char_length(btrim(description)) between 1 and 5000) not valid;
alter table public.tasks drop constraint if exists tasks_address_length;
alter table public.tasks add constraint tasks_address_length check (char_length(address_text) <= 300) not valid;
alter table public.tasks drop constraint if exists tasks_budget_max;
alter table public.tasks add constraint tasks_budget_max check (budget <= 1000000) not valid;

alter table public.bids drop constraint if exists bids_amount_max;
alter table public.bids add constraint bids_amount_max check (amount <= 1000000) not valid;
alter table public.bids drop constraint if exists bids_message_length;
alter table public.bids add constraint bids_message_length check (message is null or char_length(message) <= 1000) not valid;

alter table public.chat_messages drop constraint if exists chat_messages_body_length;
alter table public.chat_messages add constraint chat_messages_body_length check (char_length(btrim(body)) between 1 and 2000) not valid;

alter table public.ratings drop constraint if exists ratings_comment_length;
alter table public.ratings add constraint ratings_comment_length check (comment is null or char_length(comment) <= 1000) not valid;

-- ════════ 0020_safety_and_lifecycle.sql ════════
-- Safety tools and the missing ends of a job's lifecycle.
--
--   * Taskers can mark a job done, which prompts the client to pay.
--   * Either side can cancel a job that's in progress (before payment), so nobody is stuck.
--   * Users can report and block each other (required by the app stores for any app with
--     user-generated content, and worth having regardless).
--   * Users can delete their own account from inside the app (also a store requirement).

-- ── Job lifecycle ────────────────────────────────────────────────────────────────────────

alter table public.tasks add column if not exists tasker_done_at timestamptz;

alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications
  add constraint notifications_kind_check check (
    kind in ('new_bid', 'bid_accepted', 'bid_rejected', 'task_paid', 'new_review', 'task_done', 'task_cancelled')
  );

-- The hired tasker says the work is finished. Doesn't complete the task (only a verified
-- payment does); it records the moment and tells the client it's time to pay.
create or replace function public.mark_task_done(p_task_id uuid)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_tasker_name text;
  v_done_at timestamptz;
begin
  select * into v_task from public.tasks where id = p_task_id for update;
  if v_task.id is null then
    raise exception 'Task not found.';
  end if;
  if not exists (
    select 1 from public.bids
    where task_id = p_task_id and tasker_id = auth.uid() and status = 'accepted'
  ) then
    raise exception 'Only the tasker hired for this task can mark it as done.';
  end if;
  if v_task.status <> 'assigned' then
    raise exception 'This task isn''t in progress.';
  end if;
  if v_task.tasker_done_at is not null then
    return v_task.tasker_done_at;
  end if;

  update public.tasks set tasker_done_at = now() where id = p_task_id
  returning tasker_done_at into v_done_at;

  select full_name into v_tasker_name from public.profiles where id = auth.uid();
  insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
  values (
    v_task.client_id,
    'task_done',
    coalesce(nullif(v_tasker_name, ''), 'Your tasker') || ' marked the job as done',
    'Check the work, then pay for ' || v_task.title,
    p_task_id,
    auth.uid()
  );

  return v_done_at;
end;
$$;

revoke all on function public.mark_task_done(uuid) from public, anon;
grant execute on function public.mark_task_done(uuid) to authenticated;

-- Cancel a task. The client can cancel while it's open; the client or the hired tasker can
-- cancel once it's assigned, as long as it hasn't been paid. The other side is told.
create or replace function public.cancel_task(p_task_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks;
  v_tasker_id uuid;
  v_actor_name text;
begin
  select * into v_task from public.tasks where id = p_task_id for update;
  if v_task.id is null then
    raise exception 'Task not found.';
  end if;

  select tasker_id into v_tasker_id from public.bids where task_id = p_task_id and status = 'accepted';

  if v_task.status = 'open' then
    if v_task.client_id <> auth.uid() then
      raise exception 'Only the person who posted this task can cancel it.';
    end if;
  elsif v_task.status = 'assigned' then
    if auth.uid() is distinct from v_task.client_id and auth.uid() is distinct from v_tasker_id then
      raise exception 'Only the client or the hired tasker can cancel this task.';
    end if;
    if exists (select 1 from public.payments where task_id = p_task_id and status = 'succeeded') then
      raise exception 'This task has already been paid for.';
    end if;
  else
    raise exception 'This task can no longer be cancelled.';
  end if;

  update public.tasks set status = 'cancelled' where id = p_task_id;

  if v_task.status = 'assigned' and v_tasker_id is not null then
    select full_name into v_actor_name from public.profiles where id = auth.uid();
    insert into public.notifications (user_id, kind, title, body, task_id, actor_id)
    values (
      case when auth.uid() = v_task.client_id then v_tasker_id else v_task.client_id end,
      'task_cancelled',
      coalesce(nullif(v_actor_name, ''), 'The other person') || ' cancelled the job',
      v_task.title,
      p_task_id,
      auth.uid()
    );
  end if;
end;
$$;

revoke all on function public.cancel_task(uuid) from public, anon;
grant execute on function public.cancel_task(uuid) to authenticated;

-- ── Blocking ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.user_blocks (
  blocker_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  constraint user_blocks_not_self check (blocker_id <> blocked_id)
);

create index if not exists user_blocks_blocked_id_idx on public.user_blocks (blocked_id);

alter table public.user_blocks enable row level security;

-- You can see and manage who YOU blocked. Nobody can see who blocked them.
drop policy if exists "users see who they blocked" on public.user_blocks;
create policy "users see who they blocked"
  on public.user_blocks for select
  to authenticated
  using (blocker_id = auth.uid());

drop policy if exists "users can block someone" on public.user_blocks;
create policy "users can block someone"
  on public.user_blocks for insert
  to authenticated
  with check (blocker_id = auth.uid());

drop policy if exists "users can unblock someone" on public.user_blocks;
create policy "users can unblock someone"
  on public.user_blocks for delete
  to authenticated
  using (blocker_id = auth.uid());

-- True if either user has blocked the other. In `private` (not an API endpoint) because it
-- answers for any pair of users; the guards below only ever ask about the caller.
create or replace function private.is_blocked_between(p_user_a uuid, p_user_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.user_blocks
    where (blocker_id = p_user_a and blocked_id = p_user_b)
       or (blocker_id = p_user_b and blocked_id = p_user_a)
  );
$$;

create or replace function private.task_client_id(p_task_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select client_id from public.tasks where id = p_task_id;
$$;

create or replace function private.thread_other_participant(p_thread_id uuid, p_user_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select case when client_id = p_user_id then tasker_id else client_id end
  from public.chat_threads
  where id = p_thread_id and (client_id = p_user_id or tasker_id = p_user_id);
$$;

revoke all on function private.is_blocked_between(uuid, uuid) from public;
revoke all on function private.task_client_id(uuid) from public;
revoke all on function private.thread_other_participant(uuid, uuid) from public;
grant execute on function private.is_blocked_between(uuid, uuid) to authenticated;
grant execute on function private.task_client_id(uuid) to authenticated;
grant execute on function private.thread_other_participant(uuid, uuid) to authenticated;

-- A block stops new bids and new messages in both directions. SECURITY INVOKER, like the
-- guards in 0019, so current_user is the caller.
create or replace function public.guard_blocked_bid()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  -- New bids, and withdrawn bids being put back.
  if (tg_op = 'INSERT' or (old.status = 'withdrawn' and new.status = 'pending'))
     and private.is_blocked_between(auth.uid(), private.task_client_id(new.task_id)) then
    raise exception 'You can''t bid on this task.' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists bids_guard_blocked on public.bids;
create trigger bids_guard_blocked
  before insert or update on public.bids
  for each row
  execute function public.guard_blocked_bid();

create or replace function public.guard_blocked_message()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if private.is_blocked_between(auth.uid(), private.thread_other_participant(new.thread_id, auth.uid())) then
    raise exception 'You can''t send messages in this conversation.' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists chat_messages_guard_blocked on public.chat_messages;
create trigger chat_messages_guard_blocked
  before insert on public.chat_messages
  for each row
  execute function public.guard_blocked_message();

revoke all on function public.guard_blocked_bid() from public, anon, authenticated;
revoke all on function public.guard_blocked_message() from public, anon, authenticated;

-- ── Reports ──────────────────────────────────────────────────────────────────────────────
-- Filed from the app; reviewed by the operator in the Supabase dashboard (Table Editor >
-- reports), who sets `status`. Kept when either account is later deleted.

create table if not exists public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid references public.profiles (id) on delete set null,
  reported_user_id uuid references public.profiles (id) on delete set null,
  task_id uuid references public.tasks (id) on delete set null,
  reason text not null check (
    reason in ('spam', 'scam_or_fraud', 'harassment', 'inappropriate_content', 'safety_concern', 'other')
  ),
  details text check (details is null or char_length(details) <= 2000),
  status text not null default 'open' check (status in ('open', 'reviewing', 'resolved', 'dismissed')),
  created_at timestamptz not null default now()
);

create index if not exists reports_status_created_idx on public.reports (status, created_at desc);

alter table public.reports enable row level security;

drop policy if exists "users can file a report" on public.reports;
create policy "users can file a report"
  on public.reports for insert
  to authenticated
  with check (
    reporter_id = auth.uid()
    and status = 'open'
    and reported_user_id is distinct from auth.uid()
    and (reported_user_id is not null or task_id is not null)
  );

drop policy if exists "users see their own reports" on public.reports;
create policy "users see their own reports"
  on public.reports for select
  to authenticated
  using (reporter_id = auth.uid());

-- ── Account deletion ─────────────────────────────────────────────────────────────────────

-- Deleting an account removes the reviews that person wrote. Keep everyone else's rating
-- totals right when a review disappears, for whatever reason.
create or replace function public.refresh_rating_after_delete()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.profiles
  set
    rating_count = (select count(*) from public.ratings where ratee_id = old.ratee_id),
    rating_avg = coalesce((select round(avg(stars)::numeric, 2) from public.ratings where ratee_id = old.ratee_id), 0)
  where id = old.ratee_id;
  return old;
end;
$$;

drop trigger if exists ratings_refresh_after_delete on public.ratings;
create trigger ratings_refresh_after_delete
  after delete on public.ratings
  for each row
  execute function public.refresh_rating_after_delete();

revoke all on function public.refresh_rating_after_delete() from public, anon, authenticated;

-- Deletes the caller's account. Everything that hangs off their profile goes with it through
-- the existing ON DELETE CASCADE rules: their tasks, bids, messages, notifications and the
-- reviews they wrote. Refused while they have a job in progress, so the other person isn't
-- left with a half-finished, unpaid job and nobody to talk to (cancel or finish it first).
-- The app removes the user's uploaded photos through the Storage API before calling this.
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Not signed in.';
  end if;

  if exists (select 1 from public.tasks where client_id = v_user_id and status = 'assigned')
     or exists (
       select 1
       from public.bids b
       join public.tasks t on t.id = b.task_id
       where b.tasker_id = v_user_id and b.status = 'accepted' and t.status = 'assigned'
     ) then
    raise exception 'You have a job in progress. Finish or cancel it before deleting your account.';
  end if;

  delete from auth.users where id = v_user_id;
end;
$$;

revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ════════ 0021_private_task_locations.sql ════════
-- Keep a task's exact address private until someone is hired.
--
-- Until now any signed-in user could read every open task's street address and exact
-- coordinates (tasks.address_text and tasks.location), which for most tasks is somebody's
-- home. From here on:
--   * everyone sees only the task's AREA (suburb/town, tasks.area_text) and an approximate
--     map position, snapped to a grid of roughly 500 m;
--   * the exact address and coordinates are readable only by the client and the tasker
--     whose bid was accepted, through task_private_details().
--
-- Row Level Security can't hide individual columns, so this uses column privileges: the
-- `authenticated` role loses SELECT on the whole table and gets it back column by column,
-- without address_text and location. NOTE FOR LATER MIGRATIONS: a new column on tasks is
-- not readable by the app until it's added to the GRANT below.

-- ── The public area ──────────────────────────────────────────────────────────────────────

alter table public.tasks add column if not exists area_text text;

-- Existing tasks only have a full address. Derive the area from its tail ("12 Main Rd,
-- Sandton, Gauteng" -> "Sandton, Gauteng") and never copy a street address across.
update public.tasks t
set area_text = case
  when cardinality(p.parts) >= 3
    then btrim(p.parts[cardinality(p.parts) - 1]) || ', ' || btrim(p.parts[cardinality(p.parts)])
  when cardinality(p.parts) = 2 then btrim(p.parts[2])
  when t.address_text ~ '[0-9]' or btrim(t.address_text) = '' then 'Area not specified'
  else btrim(t.address_text)
end
from (select id, string_to_array(address_text, ',') as parts from public.tasks) p
where p.id = t.id and t.area_text is null;

update public.tasks set area_text = 'Area not specified' where area_text is null or btrim(area_text) = '';

alter table public.tasks alter column area_text set not null;

alter table public.tasks drop constraint if exists tasks_area_length;
alter table public.tasks add constraint tasks_area_length check (char_length(btrim(area_text)) between 2 and 120) not valid;

-- ── Column privileges ────────────────────────────────────────────────────────────────────

revoke select on public.tasks from anon, authenticated;

grant select (
  id, client_id, title, description, category, budget, status, area_text, image_url,
  scheduled_for, tasker_done_at, created_at, updated_at
) on public.tasks to authenticated;

-- ── Exact location, for the two people who need it ───────────────────────────────────────

create or replace function public.task_private_details(p_task_id uuid)
returns table (address_text text, lat double precision, lng double precision)
language sql
stable
security definer
set search_path = public, extensions
as $$
  select t.address_text, st_y(t.location::geometry), st_x(t.location::geometry)
  from public.tasks t
  where t.id = p_task_id
    and (
      t.client_id = auth.uid()
      or exists (
        select 1 from public.bids b
        where b.task_id = t.id and b.tasker_id = auth.uid() and b.status = 'accepted'
      )
    );
$$;

revoke all on function public.task_private_details(uuid) from public, anon;
grant execute on function public.task_private_details(uuid) to authenticated;

-- ── Browse search ────────────────────────────────────────────────────────────────────────
-- Now SECURITY DEFINER, because callers can no longer read tasks.location themselves. It
-- therefore does its own filtering: open tasks only (what RLS shows everyone anyway), not
-- your own, and nobody you've blocked or who has blocked you.
--
-- Both the returned position and the distance use the snapped point. Returning the exact
-- distance would let someone work out the real location by searching from three places.

drop function if exists public.nearby_open_tasks(double precision, double precision, integer, text);

create function public.nearby_open_tasks(
  lat double precision,
  lng double precision,
  radius_meters integer default 20000,
  category_filter text default null
)
returns table (
  id uuid,
  client_id uuid,
  title text,
  description text,
  category text,
  budget numeric,
  status text,
  area_text text,
  image_url text,
  scheduled_for timestamptz,
  created_at timestamptz,
  distance_meters double precision,
  task_lat double precision,
  task_lng double precision
)
language sql
stable
security definer
set search_path = public, extensions
as $$
  with origin as (
    select st_setsrid(st_makepoint(lng, lat), 4326)::geography as point
  ),
  nearby as (
    select
      t.*,
      (round(st_y(t.location::geometry)::numeric / 0.005) * 0.005)::double precision as approx_lat,
      (round(st_x(t.location::geometry)::numeric / 0.005) * 0.005)::double precision as approx_lng
    from public.tasks t, origin o
    where t.status = 'open'
      and t.client_id is distinct from auth.uid()
      and st_dwithin(t.location, o.point, least(greatest(radius_meters, 100), 100000))
      and (category_filter is null or t.category = category_filter)
      and not private.is_blocked_between(auth.uid(), t.client_id)
  )
  select
    n.id, n.client_id, n.title, n.description, n.category, n.budget, n.status, n.area_text,
    n.image_url, n.scheduled_for, n.created_at,
    st_distance(st_setsrid(st_makepoint(n.approx_lng, n.approx_lat), 4326)::geography, o.point) as distance_meters,
    n.approx_lat as task_lat,
    n.approx_lng as task_lng
  from nearby n, origin o
  order by distance_meters asc
  limit 200;
$$;

revoke all on function public.nearby_open_tasks(double precision, double precision, integer, text) from public, anon;
grant execute on function public.nearby_open_tasks(double precision, double precision, integer, text) to authenticated;
